-- GENERATED by `wfj generate` from data/book/. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("book", {
  ["86424e46b22364fb"] = { "Ricordate, fratelli miei, un tempo eravamo artigiani orgogliosi. Svolgeremo i nostri compiti attuali con la stessa precisione che usavamo nel nostro vecchio mestiere.\n\n-EVC", "." },
  ["86542accf7d3c0a5"] = { "Malygos:\n\rMalygos è noto come il Custode della Magia o il Tessitore di Incantesimi. La sua forma naturale non è quella di un drago comune, e si dice che possa cambiarla a piacimento. Visto di rado dopo il suo ritiro nell'estremo nord, ha quasi sempre l'aspetto di una creatura simile a un insetto, ma in forma di drago lui e il suo stormo hanno varie sfumature di blu.", "." },
  ["86aac270648ba089"] = { "I Barbabronzea tornarono a ⟦Ironforge=Forgiardente⟧ e ricostruirono la loro gloriosa città. Anche i Granmartello tornarono a casa, a Grim Batol. Tuttavia, la morte di Modgud aveva lasciato una macchia malvagia sulla fortezza di montagna, e i Granmartello la trovarono inabitabile.", "." },
  ["86c0c0e0bec307ee"] = { "E così vagò, e cercò. E il suo braccio restò perduto per lui. E così imprecava e ruggiva mentre camminava.\n\nMa Gri'lek da tempo aveva distolto l'orecchio dagli spiriti, ed essi erano adirati e non volevano ascoltare le sue imprecazioni.\n\nCondannato era Gri'lek. Condannato a vagare, senza il suo braccio.", "." },
  ["86cf1042f36b32cc"] = { ". . .una spirale di disperazione senza fondo. Prima mi deride e ora si è fidanzata. Quell'ingrata impostora fingeva di amarmi, quando in realtà per tutto il tempo voleva solo ferirmi. Ora dentro di me si annida un vuoto nero, che cresce a ogni istante di veglia. Il sangue che verserò è nulla in confronto alle lacrime che ho versato. . .", "." },
  ["86d40fd177b3bb09"] = { "In fondo alla ⟦Valley of Spears=Valle delle Lance⟧ sorge il sacro tempio di Maraudon. Come se questa non fosse già una trasgressione sufficiente, capirai presto perché ho chiesto a chi non è un centauro di aiutarmi nella mia difficile impresa.\n\nLaggiù, appena oltre le porte che possono varcare solo gli spiriti e i nostri sacerdoti e sacerdotesse più sacri, c'è colui che chiamano ⟦The Nameless Prophet=Profeta Senza Nome⟧. È il più elevato di tutte le tribù nelle questioni spirituali ed è uno dei più anziani di tutte le tribù.", "." },
})
